## `createEventHandler` [function]
**File:** `src/opencode/hooks.ts:432-471` | **Signature:** `function createEventHandler(
  state: AideState,
): (input: { event: OpenCodeEvent }) => Promise<void>`

```
432 : function createEventHandler(
433 :   state: AideState,
434 : ): (input: { event: OpenCodeEvent }) => Promise<void> {
435 :   const recordUsage = createOpenCodeUsageRecorder();
436 :   return async ({ event }) => {
437 :     switch (event.type) {
438 :       case "session.created":
439 :         establishContext(state, extractSessionId(event), "startup");
440 :         await handleSessionCreated(state, event);
441 :         break;
442 :       case "session.compacted": {
443 :         const session = extractSessionId(event);
444 :         establishContext(state, session, "unknown");
445 :         state.pruningTrackers.complete(session);
446 :         if (state.binary)
447 :           updateContextWindow(
448 :             state.binary,
449 :             state.cwd,
450 :             { host: "opencode", sessionId: session, actorId: session },
451 :             "compact",
452 :           );
453 :         break;
454 :       }
455 :       case "session.idle":
456 :         await handleSessionIdle(state, event);
457 :         break;
458 :       case "session.deleted":
459 :         await handleSessionDeleted(state, event);
460 :         break;
461 :       case "message.part.updated":
462 :         if (state.binary)
463 :           recordUsage(state.binary, state.cwd, event.properties.part);
464 :         await handleMessagePartUpdated(state, event);
465 :         break;
466 :       default:
467 :         // Ignore other events
468 :         break;
469 :     }
470 :   };
471 : }
```

